import{_ as a,o as i,c as e,ag as l}from"./chunks/framework.C9sp7nFj.js";const E=JSON.parse('{"title":"TCP 建立连接和断开连接的详细流程","description":"","frontmatter":{},"headers":[],"relativePath":"browser/tcp.md","filePath":"browser/tcp.md"}'),n={name:"browser/tcp.md"};function t(o,s,p,r,c,d){return i(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="tcp-建立连接和断开连接的详细流程" tabindex="-1">TCP 建立连接和断开连接的详细流程 <a class="header-anchor" href="#tcp-建立连接和断开连接的详细流程" aria-label="Permalink to &quot;TCP 建立连接和断开连接的详细流程&quot;">​</a></h1><p>TCP（传输控制协议）是一种面向连接的、可靠的传输层协议，其建立连接和断开连接都有严谨的流程。下文默认由<strong>客户端主动发起</strong>连接与关闭。</p><h2 id="tcp-建立连接-三次握手" tabindex="-1">TCP 建立连接（三次握手） <a class="header-anchor" href="#tcp-建立连接-三次握手" aria-label="Permalink to &quot;TCP 建立连接（三次握手）&quot;">​</a></h2><h3 id="流程图" tabindex="-1">流程图 <a class="header-anchor" href="#流程图" aria-label="Permalink to &quot;流程图&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as 客户端</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as 服务器</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over S: LISTEN</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: ① SYN seq=x</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C: SYN_SENT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;C: ② SYN+ACK seq=y, ack=x+1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over S: SYN_RCVD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: ③ ACK seq=x+1, ack=y+1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C,S: ESTABLISHED</span></span></code></pre></div><h3 id="为什么需要三次握手" tabindex="-1">为什么需要三次握手 <a class="header-anchor" href="#为什么需要三次握手" aria-label="Permalink to &quot;为什么需要三次握手&quot;">​</a></h3><ol><li><strong>双方都确认自己的发送、对方的接收能力</strong>：两次只能确认「我能发、你能收」中的一部分；第三次握手让服务器也确认「客户端能收到我的包」。</li><li><strong>同步双方初始序列号（ISN）</strong>：后续可靠传输、重传、有序交付都依赖这个起点。</li><li><strong>防止历史重复 SYN 误建连接</strong>：网络中可能残留旧的 SYN。若只用两次握手，服务器一收到旧 SYN 就进入就绪，可能白白占用资源；第三次握手要求客户端再确认一次，旧连接无法完成，会被丢弃。</li></ol><h3 id="详细步骤" tabindex="-1">详细步骤 <a class="header-anchor" href="#详细步骤" aria-label="Permalink to &quot;详细步骤&quot;">​</a></h3><ol><li><p><strong>准备阶段</strong></p><ul><li>服务器处于 <code>LISTEN</code>，等待连接。</li><li>客户端从 <code>CLOSED</code> 准备发起连接。</li></ul></li><li><p><strong>第一次握手（客户端发 SYN）</strong></p><ul><li>客户端发送 SYN 报文，携带随机初始序列号 <code>seq=x</code>。</li><li>客户端进入 <code>SYN_SENT</code>。</li></ul></li><li><p><strong>第二次握手（服务器回 SYN + ACK）</strong></p><ul><li>服务器回复 SYN + ACK：自身初始序列号 <code>seq=y</code>，确认号 <code>ack=x+1</code>。</li><li>服务器进入 <code>SYN_RCVD</code>。</li></ul></li><li><p><strong>第三次握手（客户端发 ACK）</strong></p><ul><li>客户端发送 ACK：<code>seq=x+1</code>，<code>ack=y+1</code>（该 ACK 也可以捎带数据）。</li><li>客户端进入 <code>ESTABLISHED</code>；服务器收到后也进入 <code>ESTABLISHED</code>，连接建立完成。</li></ul></li></ol><h2 id="tcp-断开连接-四次挥手" tabindex="-1">TCP 断开连接（四次挥手） <a class="header-anchor" href="#tcp-断开连接-四次挥手" aria-label="Permalink to &quot;TCP 断开连接（四次挥手）&quot;">​</a></h2><h3 id="流程图-1" tabindex="-1">流程图 <a class="header-anchor" href="#流程图-1" aria-label="Permalink to &quot;流程图&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as 客户端</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as 服务器</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C,S: ESTABLISHED</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: ① FIN seq=u</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C: FIN_WAIT_1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;C: ② ACK ack=u+1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over S: CLOSE_WAIT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C: FIN_WAIT_2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note right of S: 半关闭：服务端仍可发送剩余数据</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;C: ③ FIN seq=w, ack=u+1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over S: LAST_ACK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: ④ ACK ack=w+1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C: TIME_WAIT（约 2MSL）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over S: CLOSED</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C: CLOSED</span></span></code></pre></div><h3 id="为什么是四次挥手" tabindex="-1">为什么是四次挥手 <a class="header-anchor" href="#为什么是四次挥手" aria-label="Permalink to &quot;为什么是四次挥手&quot;">​</a></h3><p>TCP 是<strong>全双工</strong>的：每个方向各自独立关闭。</p><ul><li>客户端发 FIN，只表示「我这边不再发数据了」，但还可以继续收。</li><li>服务器先 ACK 确认收到 FIN（进入 <code>CLOSE_WAIT</code>），此时它可能还有数据要发，所以不能马上也 FIN。</li><li>等服务器发完剩余数据后再发自己的 FIN，客户端再 ACK。于是常见是 <strong>4 次</strong>。</li></ul><p>若服务器收到 FIN 后立刻也没有数据要发，可以把第 ② 步的 ACK 和第 ③ 步的 FIN <strong>合并成一个报文</strong>，关闭过程就会变成「三次挥手」。</p><h3 id="详细步骤-1" tabindex="-1">详细步骤 <a class="header-anchor" href="#详细步骤-1" aria-label="Permalink to &quot;详细步骤&quot;">​</a></h3><ol><li><p><strong>第一次挥手（客户端发 FIN）</strong></p><ul><li>客户端发送 FIN，<code>seq=u</code>，表示本端发送完毕。</li><li>客户端进入 <code>FIN_WAIT_1</code>。</li></ul></li><li><p><strong>第二次挥手（服务器回 ACK）</strong></p><ul><li>服务器回复 ACK，<code>ack=u+1</code>，<code>seq=v</code>。</li><li>服务器进入 <code>CLOSE_WAIT</code>；客户端收到后进入 <code>FIN_WAIT_2</code>。</li><li>此时是半关闭：客户端→服务器方向已关，服务器→客户端仍可传数据。</li></ul></li><li><p><strong>第三次挥手（服务器发 FIN）</strong></p><ul><li>服务器发完剩余数据后发送 FIN，<code>seq=w</code>，<code>ack=u+1</code>。</li><li>服务器进入 <code>LAST_ACK</code>。</li></ul></li><li><p><strong>第四次挥手（客户端回 ACK）</strong></p><ul><li>客户端发送 ACK，<code>ack=w+1</code>，<code>seq=u+1</code>，并进入 <code>TIME_WAIT</code>。</li><li>服务器收到 ACK 后进入 <code>CLOSED</code>。</li><li>客户端在 <code>TIME_WAIT</code> 停留约 <strong>2MSL</strong>（MSL：最长报文段寿命）后进入 <code>CLOSED</code>。</li></ul></li></ol><h3 id="time-wait-的作用" tabindex="-1">TIME_WAIT 的作用 <a class="header-anchor" href="#time-wait-的作用" aria-label="Permalink to &quot;TIME_WAIT 的作用&quot;">​</a></h3><p>主动关闭方进入 <code>TIME_WAIT</code>，主要是为了：</p><ol><li><strong>保证最后的 ACK 能送达</strong>：若 ACK 丢失，对端会重传 FIN，本端仍在 TIME_WAIT，可以再次回复 ACK。</li><li><strong>让旧连接的延迟报文在网络中消亡</strong>：避免新连接（相同四元组）被旧包干扰。</li></ol><p>因此会出现「端口短暂占用 / Address already in use」一类现象；不要轻易把 TIME_WAIT 改得过短。</p><h2 id="异常断开-rst" tabindex="-1">异常断开：RST <a class="header-anchor" href="#异常断开-rst" aria-label="Permalink to &quot;异常断开：RST&quot;">​</a></h2><p>正常关闭走 FIN 四次挥手。下列情况常见 <strong>RST（Reset）</strong>，连接被立即复位，没有完整挥手：</p><ul><li>对端端口未监听、连接不存在</li><li>进程崩溃或调用强制中止（如 <code>abort</code>）</li><li>收到不符合当前状态的报文</li></ul><p>RST 表示「连接立刻作废」，不保证对端还有数据可读完。</p><h2 id="和-http-的关系" tabindex="-1">和 HTTP 的关系 <a class="header-anchor" href="#和-http-的关系" aria-label="Permalink to &quot;和 HTTP 的关系&quot;">​</a></h2><p>浏览器访问网页时，DNS 拿到 IP 后会先建立 TCP 连接，HTTP 请求跑在已 <code>ESTABLISHED</code> 的连接上。HTTP/1.1 Keep-Alive、HTTP/2 多路复用，都是为了少做握手/挥手，降低建连开销。</p>`,28)])])}const k=a(n,[["render",t]]);export{E as __pageData,k as default};
